(function(root){'use strict';
const BANNED=[/prototype/i,/production system/i,/production engine/i,/product[- ]intelligence note/i,/future commerce opportunity/i,/support role still/i,/second support role/i,/role being completed/i,/current story/i,/eligible after product verification/i,/automatically escalating merchandise/i,/treatment value,? not filler/i,/implementation sheets/i,/separate solution/i];
function hasBanned(s){return BANNED.some(rx=>rx.test(String(s||'')));}
function pageModel(ctx){ctx=ctx||{};const digital=!!ctx.digital;return[
 {id:'overview',title:'Your Keneflex Plan',visuals:1,copy:'What to do now, what Keneflex recommends, and what to watch.'},
 {id:'support',title:'Use your support where it helps',visuals:2,copy:'Use the selected support for the job Keneflex chose it for. Fit should feel secure, not numb, pinching, or circulation-limiting.'},
 {id:'movement',title:'Keep movement comfortable',visuals:3,copy:'Use gentle, comfortable motion. Stop or change a movement if symptoms clearly increase.'},
 {id:'recovery',title:'Recover after aggravating use',visuals:2,copy:'Reduce the aggravating load, use the selected recovery option as directed, then reassess how the area feels.'},
 {id:'activity',title:'Change what keeps setting it off',visuals:2,copy:'Shorten long sessions, reduce repeated gripping or awkward positions, and change the provoking pattern before it builds.'},
 ...(digital?[{id:'setup',title:'Your setup may be contributing',visuals:3,copy:'Try the no-cost setup changes first. Optional equipment improvements can be added without making you shop a catalog.'}]:[]),
 {id:'followup',title:'Tell Keneflex what changed',visuals:4,copy:'Better, partly better, not better, or something changed — that tells Keneflex what to do next.'}
 ];}
root.KFX047={BANNED,hasBanned,pageModel};
if(typeof document==='undefined'||typeof window==='undefined')return;
function esc(s){return String(s==null?'':s).replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));}
function currentContext(){let t=null;try{if(root.KFX046&&state&&state.kfx046)t=root.KFX046.activeThread(state.kfx046);}catch(e){}const triggers=t&&t.triggers||[];const digital=triggers.some(x=>['phone','scrolling','computer','typing','mouse'].includes(x))||/phone|computer|typing|keyboard|mouse|scroll/i.test([state&&state.opening,state&&state.triggerSummary,state&&state.activity].filter(Boolean).join(' '));const side=t&&t.side||state&&state.side||'';const area=t&&((t.locations&&t.locations[0])||(t.areas&&t.areas.join(' + ')))||'the area you described';return{t,digital,side,area};}
function svgPhone(){return `<svg viewBox="0 0 260 120" role="img" aria-label="Phone use: reduce one-handed thumb reach"><g transform="translate(8 9)"><rect x="8" y="5" width="72" height="102" rx="14" fill="#fff" stroke="#174b46" stroke-width="4"/><path d="M58 77 C43 60 35 50 28 39" fill="none" stroke="#ef8c68" stroke-width="13" stroke-linecap="round"/><path d="M21 25 Q43 42 65 28" fill="none" stroke="#d16b4e" stroke-width="4"/><text x="94" y="32" font-size="14" font-weight="800" fill="#174b46">Less helpful</text><text x="94" y="53" font-size="12" fill="#5a6d68">Long one-handed reach</text></g><path d="M145 61 H174" stroke="#92ad34" stroke-width="5"/><path d="M168 54 L178 61 L168 68" fill="#92ad34"/><g transform="translate(182 9)"><rect x="8" y="5" width="60" height="78" rx="12" fill="#fff" stroke="#174b46" stroke-width="4"/><path d="M0 92 H79" stroke="#174b46" stroke-width="6"/><path d="M39 83 V94" stroke="#174b46" stroke-width="5"/><text x="-4" y="112" font-size="12" font-weight="800" fill="#174b46">Prop it up when practical</text></g></svg>`;}
function svgWrist(){return `<svg viewBox="0 0 260 120" role="img" aria-label="Reset wrist toward a comfortable straight position"><g transform="translate(4 20)"><rect x="10" y="34" width="75" height="28" rx="13" fill="#ef8c68"/><path d="M81 47 L121 26" stroke="#ef8c68" stroke-width="19" stroke-linecap="round"/><text x="16" y="16" font-size="12" font-weight="800" fill="#174b46">Bent for a long time</text></g><path d="M132 60 H158" stroke="#92ad34" stroke-width="5"/><path d="M152 53 L162 60 L152 67" fill="#92ad34"/><g transform="translate(166 20)"><rect x="8" y="34" width="77" height="28" rx="13" fill="#ef8c68"/><path d="M82 47 H123" stroke="#ef8c68" stroke-width="19" stroke-linecap="round"/><path d="M8 78 H124" stroke="#174b46" stroke-width="4"/><text x="17" y="16" font-size="12" font-weight="800" fill="#174b46">Comfortably straighter</text></g></svg>`;}
function svgThumb(){return `<svg viewBox="0 0 260 120" role="img" aria-label="Gentle thumb motion within a comfortable range"><g transform="translate(16 10)"><path d="M32 78 C48 54 69 45 90 48 C106 50 111 64 103 76 C94 90 75 96 55 93 C43 91 36 86 32 78Z" fill="#ef8c68"/><path d="M82 51 C77 31 80 17 91 13 C100 10 107 16 105 26 C102 41 96 52 87 61" fill="#ef8c68"/><path d="M106 31 Q127 42 126 65" fill="none" stroke="#174b46" stroke-width="4" stroke-linecap="round"/><path d="M121 57 L126 66 L117 64" fill="#d9eb65"/></g><text x="145" y="48" font-size="14" font-weight="800" fill="#174b46">Easy range only</text><text x="145" y="69" font-size="12" fill="#5a6d68">No forcing into pain</text></svg>`;}
function svgCold(){return `<svg viewBox="0 0 260 120" role="img" aria-label="Recovery sequence after aggravating use"><g transform="translate(8 16)"><circle cx="32" cy="42" r="25" fill="#eef4ef"/><text x="19" y="49" font-size="26">✋</text><text x="4" y="91" font-size="11" font-weight="800" fill="#174b46">Reduce the load</text></g><path d="M80 58 H105" stroke="#92ad34" stroke-width="5"/><path d="M99 51 L109 58 L99 65" fill="#92ad34"/><g transform="translate(114 16)"><rect x="5" y="15" width="58" height="50" rx="12" fill="#cfe7ef" stroke="#174b46" stroke-width="3"/><text x="16" y="48" font-size="25">❄</text><text x="1" y="91" font-size="11" font-weight="800" fill="#174b46">Use recovery as directed</text></g><path d="M183 58 H205" stroke="#92ad34" stroke-width="5"/><path d="M199 51 L209 58 L199 65" fill="#92ad34"/><g transform="translate(212 16)"><circle cx="23" cy="40" r="22" fill="#eef4ef"/><path d="M12 42 L20 50 L36 30" fill="none" stroke="#174b46" stroke-width="4"/><text x="-5" y="91" font-size="11" font-weight="800" fill="#174b46">Re-check</text></g></svg>`;}
function svgFollow(){return `<svg viewBox="0 0 360 86" role="img" aria-label="Four follow-up states"><g font-family="Arial" font-size="12" font-weight="800" text-anchor="middle"><rect x="5" y="10" width="80" height="54" rx="14" fill="#e7f3e9"/><text x="45" y="35" fill="#174b46">✓ Better</text><text x="45" y="51" font-size="10" fill="#5d7069">keep what works</text><rect x="94" y="10" width="80" height="54" rx="14" fill="#f0f4df"/><text x="134" y="35" fill="#174b46">◐ Partly</text><text x="134" y="51" font-size="10" fill="#5d7069">say what changed</text><rect x="183" y="10" width="80" height="54" rx="14" fill="#f7eee6"/><text x="223" y="35" fill="#174b46">— Not better</text><text x="223" y="51" font-size="10" fill="#5d7069">rethink the plan</text><rect x="272" y="10" width="80" height="54" rx="14" fill="#f8e7e4"/><text x="312" y="35" fill="#8a4035">! Changed</text><text x="312" y="51" font-size="10" fill="#6f5d59">new/worse matters</text></g></svg>`;}
function visualPlanHTML(focus){const c=currentContext(),digital=c.digital;const area=[c.side,c.area].filter(Boolean).join(' ');return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Your Keneflex Plan</title><style>:root{--ink:#173f3b;--muted:#61736d;--line:#d9e1dc;--cream:#fbf7ef;--lime:#d9eb65;--teal:#174b46}*{box-sizing:border-box}body{margin:0;background:var(--cream);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Arial,sans-serif}.wrap{max-width:900px;margin:auto;padding:26px}.hero{background:linear-gradient(135deg,#0f514b,#177365);color:#fff;border-radius:28px;padding:28px}.hero h1{font-size:38px;margin:5px 0 10px}.hero p{margin:0;line-height:1.5;max-width:680px}.facts{margin-top:16px;display:flex;gap:8px;flex-wrap:wrap}.pill{background:rgba(255,255,255,.14);border-radius:999px;padding:8px 11px;font-size:12px;font-weight:800}.section{background:#fff;border:1px solid var(--line);border-radius:24px;padding:22px;margin-top:16px}.section h2{font-size:25px;margin:0 0 7px}.section>p{color:var(--muted);line-height:1.5;margin:0 0 15px}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.card{border:1px solid var(--line);border-radius:18px;padding:16px;background:#fcfdfb}.card h3{font-size:17px;margin:5px 0 7px}.card p{font-size:13px;line-height:1.48;color:var(--muted);margin:0}.art{height:130px;border-radius:15px;background:linear-gradient(135deg,#edf5ef,#f7f2d9);display:flex;align-items:center;justify-content:center;overflow:hidden}.art svg{width:96%;height:112px}.product{display:grid;grid-template-columns:110px 1fr;gap:16px;align-items:center}.product img{width:105px;height:105px;object-fit:contain;background:#f7f9f7;border-radius:16px}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.step{background:#f6f9f5;border-radius:16px;padding:13px}.step b{display:block;margin-bottom:4px}.warn{border-left:5px solid #d78c35;background:#fff3df;border-radius:14px;padding:13px;margin-top:13px;font-size:13px;line-height:1.5}.optional{border-left:5px solid var(--lime)}.toolbar{position:sticky;top:0;z-index:3;background:rgba(251,247,239,.95);backdrop-filter:blur(8px);padding:10px 0;display:flex;justify-content:flex-end}.toolbar button{border:0;border-radius:12px;background:var(--teal);color:#fff;padding:10px 14px;font-weight:900}.kicker{font-size:11px;letter-spacing:.12em;font-weight:900;text-transform:uppercase;color:#73847f}@media(max-width:650px){.wrap{padding:14px}.hero h1{font-size:31px}.cards,.steps{grid-template-columns:1fr}.product{grid-template-columns:82px 1fr}.product img{width:78px;height:78px}.section{padding:17px}.art{height:118px}}@media print{.toolbar{display:none}.wrap{padding:0}.section,.hero{break-inside:avoid}}</style></head><body><div class="wrap"><div class="toolbar"><button onclick="window.print()">Print / save my plan</button></div><section class="hero"><div class="kicker" style="color:#cbded9">Your Keneflex Plan</div><h1>Here’s what Keneflex recommends.</h1><p>A simple plan built around what you told Keneflex — what to use, what to change, and what to watch.</p><div class="facts"><span class="pill">${esc(area||'Your hand/wrist problem')}</span>${digital?'<span class="pill">Phone/computer use matters here</span>':''}</div></section>
<section class="section" id="start"><div class="kicker">Start here</div><h2>Do these things first</h2><div class="cards"><article class="card"><h3>1. Reduce what keeps setting it off</h3><p>Shorten long provoking sessions and take a brief reset before symptoms build.</p></article><article class="card"><h3>2. Use support only for its intended job</h3><p>The support should help without causing numbness, pressure points, or blocking function you need.</p></article><article class="card"><h3>3. Recover after aggravating use</h3><p>If the selected cold/recovery option feels helpful, use it according to its directions and protect the skin.</p></article><article class="card"><h3>4. Keep comfortable motion</h3><p>Move gently in a comfortable range rather than forcing stretches into symptoms.</p></article></div></section>
<section class="section" id="support"><div class="kicker">Your support</div><h2>Use the selected support where it helps</h2><div class="product"><img src="https://www.neo-g.com/cdn/shop/files/722-13-Box_R_1080x.png?v=1725268865" alt="Neo G Airflow Wrist and Thumb Support"><div><h3 style="margin:0 0 6px">Neo G Airflow Wrist & Thumb Support</h3><p style="margin:0;color:var(--muted);line-height:1.45">Keneflex selected this for the current hand/wrist/thumb pathway because it can support the area while preserving more useful movement than a rigid immobilizer.</p></div></div><div class="steps" style="margin-top:15px"><div class="step"><b>Position</b><span>Center the support where it is intended to control the wrist/thumb.</span></div><div class="step"><b>Fit</b><span>Secure, not painfully tight. Stop if it causes numbness, color change, or pressure points.</span></div><div class="step"><b>Use</b><span>Follow the selected product directions and the use context Keneflex gives you.</span></div></div></section>
<section class="section" id="movement"><div class="kicker">Movement</div><h2>Keep movement comfortable</h2><p>The pictures show the idea before the words: relaxed hand, easy thumb motion, and a comfortable wrist reset.</p><div class="cards"><article class="card"><div class="art">${svgThumb()}</div><h3>Easy thumb motion</h3><p>Move through the range that feels comfortable. Do not force the painful end range.</p></article><article class="card"><div class="art">${svgWrist()}</div><h3>Reset wrist position</h3><p>After sustained device use, let the wrist return toward a relaxed, straighter position.</p></article></div><div class="warn"><b>Change or stop the movement</b> if it clearly increases pain, numbness, tingling, weakness, swelling, or symptoms that do not settle after stopping.</div></section>
<section class="section" id="recovery"><div class="kicker">Recovery</div><h2>After aggravating use</h2><div class="art">${svgCold()}</div><p style="margin-top:12px">Reduce the aggravating load first. Then use the selected recovery option as directed if it feels helpful. Re-check how the area responds before repeating the same load.</p></section>
<section class="section" id="activity"><div class="kicker">Activity changes</div><h2>Change what keeps setting it off</h2><div class="cards"><article class="card"><div class="art">${svgPhone()}</div><h3>Reduce repeated phone reach</h3><p>Prop the phone when practical, switch hands when that genuinely reduces the repeated motion, and break up long scrolling sessions.</p></article><article class="card"><div class="art">${svgWrist()}</div><h3>Bring the work closer</h3><p>Avoid long periods of reaching or holding the wrist at an extreme angle. Small setup changes can reduce the provoking load.</p></article></div></section>
${digital?`<section class="section optional" id="setup"><div class="kicker">Optional setup improvements</div><h2>Your setup may be contributing, too</h2><p>Try the no-cost changes above first. If equipment changes are worth adding, Keneflex will narrow each useful category to its best-fitting option for you. You decide whether to add an optional improvement; you should not have to shop a shelf of mice, stands, keyboards or phone accessories.</p><div class="cards"><article class="card"><h3>Highest priority</h3><p>Address the setup factor most closely tied to your provoking motion first.</p></article><article class="card"><h3>Already have something?</h3><p>Tell Keneflex what you own. It should be evaluated for function, fit and condition before recommending another purchase.</p></article></div></section>`:''}
<section class="section" id="followup"><div class="kicker">What happens next</div><h2>Tell Keneflex what changed</h2><div class="art" style="height:95px">${svgFollow()}</div><p style="margin-top:12px">If only one part improves, say which one. If something is new or meaningfully worse, tell Keneflex that first because it may change the next step.</p></section>
<section class="section"><div class="kicker">Safety</div><h2>Use the exact product directions</h2><p>Product-specific fit, wear time, skin precautions, cleaning, contraindications and interactions stay consistent with the manufacturer’s current labeling. Keneflex adds the person-specific reason the product is in your plan.</p></section></div><script>if(location.hash){setTimeout(()=>{const e=document.querySelector(location.hash);if(e)e.scrollIntoView()},50)}<\/script></body></html>`;}
function openVisualPlan(focus){const w=window.open('','_blank');if(!w)return;w.document.open();w.document.write(visualPlanHTML(focus));w.document.close();if(focus)setTimeout(()=>{try{w.location.hash=focus}catch(e){}},30);}
function addStyles(){if(document.getElementById('kfx047style'))return;const s=document.createElement('style');s.id='kfx047style';s.textContent=`#solutionView .tag{display:none!important}#solutionView .planRole{text-transform:none!important;letter-spacing:0!important;font-size:12px!important;color:#5f756e!important}.kfx047hidden{display:none!important}.kfxVPacketPrice{display:none!important}.kfxVPacketChips{display:none!important}#kfxVPacketValue,#kfxVWorkspace{background:#fff!important}.kfx047simple{border-left:4px solid var(--lime)!important}`;document.head.appendChild(s);}
function rewriteMain(){addStyles();const hero=document.querySelector('#solutionView .solHero h1');if(hero)hero.textContent='Here’s what Keneflex recommends.';const lead=document.getElementById('solutionLead');if(lead)lead.textContent='A simple plan built around what you told Keneflex — what to use, what to change, and what to watch.';const labels=[['supportItem','Support'],['coldItem','Recovery'],['topicalItem','Optional comfort']];labels.forEach(([id,text])=>{const e=document.querySelector('#'+id+' .planRole');if(e)e.textContent=text});document.querySelectorAll('#solutionView .planState').forEach(e=>{const t=e.textContent||'';if(/^BUY/i.test(t))e.textContent='Recommended';else if(/^KEEP/i.test(t))e.textContent='Use yours';else if(/^REMOVE/i.test(t))e.textContent='Not included'});document.querySelectorAll('#solutionView h2').forEach(h=>{if(/Adjust my solution|Adjust this plan/i.test(h.textContent))h.textContent="Something about this plan doesn't work for me";if(/Want to see the homework/i.test(h.textContent))h.textContent='Why Keneflex chose this';if(/What I did not add/i.test(h.textContent))h.textContent='What Keneflex left out'});const tune=document.querySelector('#solutionView .tune .help');if(tune)tune.textContent="Tell Keneflex what doesn't fit your real life. Keneflex will rework the plan without handing the shopping decision back to you.";const cart=document.getElementById('cartPreviewBtn');if(cart)cart.textContent='Continue with this plan →';const packet=document.getElementById('kfxVPacketValue');if(packet){const h=packet.querySelector('h3');if(h)h.textContent='Your Keneflex Plan';const p=packet.querySelector('p');if(p)p.textContent='Your personalized actions, product-use guidance, movement, recovery and follow-up are already assembled for you.';const b=packet.querySelector('button');if(b)b.textContent='View / save my Keneflex Plan →';packet.classList.add('kfx047simple')}
const ws=document.getElementById('kfxVWorkspace');if(ws){const eyebrow=ws.querySelector('.eyebrow');if(eyebrow)eyebrow.textContent='OPTIONAL SETUP IMPROVEMENTS';const h=ws.querySelector('h3');if(h)h.textContent='Your setup may be contributing, too.';const p=ws.querySelector('p');if(p)p.textContent='Keneflex noticed that phone or computer use matters in your story. Start with the no-cost changes; optional equipment improvements can be added later.';const tag=ws.querySelector('.kfxVWorkspaceTag');if(tag)tag.textContent='Optional';const b=ws.querySelector('button');if(b)b.textContent='See setup changes →';ws.classList.add('kfx047simple')}
document.querySelectorAll('#solutionView p,#solutionView div,#solutionView span').forEach(e=>{if(e.children.length>3)return;const t=(e.textContent||'').trim();if(!t||!hasBanned(t))return;if(/source transparency/i.test(e.closest('details')?.querySelector('summary')?.textContent||'')){e.textContent='Keneflex compares product function, fit, manufacturer information, safety information and the details you shared.';return;}const box=e.closest('.notice,.kfxSCard,.kfxSWhole,.kfxKRole,.kfxQBanner,.kfxRBanner');if(box)box.classList.add('kfx047hidden');});
const total=document.getElementById('total');const tb=total&&total.closest('.block');if(tb){const help=tb.querySelector('.help');if(help)help.textContent='Product total. Your Keneflex Plan is part of the recommendation.'}
}
function visibleLeaks(doc){const out=[];doc.querySelectorAll('body *').forEach(e=>{if(e.children.length)return;const style=doc.defaultView&&doc.defaultView.getComputedStyle?doc.defaultView.getComputedStyle(e):null;if(style&&(style.display==='none'||style.visibility==='hidden'))return;const t=(e.textContent||'').trim();if(t&&hasBanned(t))out.push(t)});return out;}
document.addEventListener('click',e=>{const t=e.target&&e.target.closest&&e.target.closest('#kfxVPacketBtn,#kfxHomePlanBtn,#kfxVWorkspaceBtn,[data-open="home"]');if(!t)return;e.preventDefault();e.stopImmediatePropagation();openVisualPlan(t.id==='kfxVWorkspaceBtn'?'setup':'start');},true);
const mo=new MutationObserver(()=>rewriteMain());mo.observe(document.body,{subtree:true,childList:true,characterData:true});rewriteMain();root.KFX047Audit=function(){rewriteMain();const leaks=visibleLeaks(document);return{build:'0.4.7',leaks,pass:leaks.length===0,pages:pageModel(currentContext())};};document.title='Keneflex Prototype 0.4.7';const eb=document.querySelector('#intro .hero .eyebrow');if(eb)eb.textContent='Prototype 0.4.7 • visual-first P0 release candidate';
})(typeof window!=='undefined'?window:globalThis);
